import {movieService} from './services/movie-service.js';import {runtimeError,delaySearch} from './services/runtime-service.js';
let items=[],daily=null,genres=[],query='',filter='all',list='all',region='AZ',error='',loading=false,generation=0,page=1;
export async function initMovies(){try{const results=await Promise.allSettled([movieService.get('trending'),movieService.get('daily'),movieService.get('genres')]);if(results[0].status==='fulfilled')items=results[0].value.movies;else throw results[0].reason;daily=results[1].status==='fulfilled'?results[1].value:null;genres=results[2].status==='fulfilled'?results[2].value.genres:[];error='';}catch(e){items=[];daily=null;error=runtimeError(e);}return items;}
function card(m,h){const {esc,icon}=h;return `<article class="movie-card"><button class="poster tmdb-poster" data-film="detail" data-id="${m.id}" aria-label="${esc(m.title)} haqqında">${m.poster?`<img src="${esc(m.poster)}" loading="lazy" decoding="async" alt="${esc(m.title)} posteri">`:'<span>Poster yoxdur</span>'}</button><div class="row between"><h3>${esc(m.title)}</h3><button data-film="favorite" data-id="${m.id}" aria-label="Sevimlilər" aria-pressed="${h.data.favorites.includes(m.id)}">${icon('heart')}</button></div><div class="movie-meta"><span>${esc(m.year)}</span><span>★ ${esc(m.rating)}</span></div></article>`;}
export function dailyMovieHTML(h){if(!daily)return `<section class="card"><h2>Günün filmi</h2><p class="muted">${h.esc(error||'Bu gün üçün film seçilməyib.')}</p><button class="text-btn" data-film="retry">Yenidən yoxla</button></section>`;return `<section class="card movie-hero real-movie-hero">${daily.backdrop?`<img class="movie-backdrop" src="${h.esc(daily.backdrop)}" alt="" loading="lazy">`:''}<div class="hero-content"><span class="pill">GÜNÜN FİLMİ</span><h2>${h.esc(daily.title)}</h2><p>${h.esc(daily.year)} · ★ ${h.esc(daily.rating)}</p><p>${h.esc(daily.description.slice(0,140))}</p><div class="row"><button class="btn" data-film="detail" data-id="${daily.id}">Film haqqında</button><button class="icon-btn" data-film="favorite" data-id="${daily.id}" aria-label="Günün filmini sevimlilərə əlavə et" aria-pressed="${h.data.favorites.includes(daily.id)}">${h.icon('heart')}</button></div></div></section>`;}
export function discoverHTML(h){return h.heading('Bu axşam nə izləyək?','Real film məlumatları. Seçim sənin əhvalına uyğun olsun.')+`<section class="card recommend"><div class="row between"><div><h2>Bu axşam nə izləyim?</h2><p>Əhvalını, janrı və vaxtını seç.</p></div><button class="btn primary" data-film="recommend">Mənim üçün seç</button></div></section><div class="toolbar"><div class="search">${h.icon('search')}<input id="real-film-search" type="search" maxlength="100" value="${h.esc(query)}" placeholder="Film axtar…" aria-label="Film axtarışı"></div><select id="real-film-list" aria-label="Film siyahısı">${[['all','Trend filmlər'],['favorite','Sevimlilər'],['watchlist','İzləniləcək'],['watched','İzlənmiş']].map(([v,l])=>`<option value="${v}" ${list===v?'selected':''}>${l}</option>`).join('')}</select><select id="film-region" aria-label="İzləmə regionu"><option ${region==='AZ'?'selected':''}>AZ</option><option ${region==='TR'?'selected':''}>TR</option><option ${region==='US'?'selected':''}>US</option></select></div><div class="chips" style="margin-bottom:24px"><button class="chip ${filter==='all'?'active':''}" data-film="genre" data-id="all">Hamısı</button>${genres.slice(0,8).map(g=>`<button class="chip ${String(g.id)===filter?'active':''}" data-film="genre" data-id="${g.id}">${h.esc(g.name)}</button>`).join('')}</div><div id="film-status" role="status" class="muted">${loading?'Yüklənir…':h.esc(error)}</div><div class="movies-grid" id="real-film-results">${results(h)}</div><div class="row" style="margin-top:20px"><button class="btn" data-film="popular">Populyar filmlər</button><button class="btn" data-film="more">Daha çox</button></div><footer class="tmdb-credit"><a href="https://www.themoviedb.org" target="_blank" rel="noopener noreferrer"><img src="assets/icons/tmdb.svg" alt="TMDB" width="55" height="40"></a><p>This product uses the TMDB API but is not endorsed or certified by TMDB.</p><p>İzləmə platforması məlumatları: JustWatch. Regiona görə əlçatanlıq dəyişə bilər.</p></footer>`;}
function results(h){const filtered=items.filter(m=>filter==='all'||m.genreIds.includes(Number(filter)));return filtered.map(m=>card(m,h)).join('')||'<div class="empty">Uyğun film yoxdur. Axtarışı və ya filtrləri dəyiş.</div>';}
export function bindMovies(h){const root=document.querySelector('#content');root.querySelector('#real-film-search')?.addEventListener('input',delaySearch(async e=>{query=e.target.value;const epoch=++generation;try{const data=await movieService.get(query.trim()?'search':'trending',query.trim()?{query}:{});if(epoch!==generation)return;items=data.movies;error='';root.querySelector('#real-film-results').innerHTML=results(h);root.querySelector('#film-status').textContent='';}catch(err){root.querySelector('#film-status').textContent=runtimeError(err);}}));root.querySelector('#film-region')?.addEventListener('change',e=>region=e.target.value);root.querySelector('#real-film-list')?.addEventListener('change',async e=>{list=e.target.value;try{if(list==='all')items=(await movieService.get('trending')).movies;else {const key={favorite:'favorites',watchlist:'watchlist',watched:'watched'}[list];const ids=h.data[key].filter(id=>/^\d+$/.test(id));items=(await Promise.all(ids.slice(0,30).map(id=>movieService.get('detail',{id,region}))));if(h.data[key].length&&!ids.length)error='Əvvəlki kataloq seçimlərin saxlanılıb; TMDB ID-si olmayan qeydlər burada göstərilmir.';}h.render();}catch(err){h.toast(runtimeError(err));}});
root.querySelectorAll('[data-film]').forEach(b=>b.onclick=async()=>{try{const action=b.dataset.film,id=b.dataset.id;if(action==='detail')await detail(id,h);if(action==='favorite')await h.toggle('favorite',id);if(action==='genre'){filter=id;h.render();}if(action==='retry'){await initMovies();h.render();}if(action==='recommend')recommend(h);if(action==='popular'||action==='more'){page=action==='more'?Math.min(page+1,10):1;const result=await movieService.get(query.trim()?'search':action==='popular'?'popular':'recommend',{query,page});items=result.movies;h.render();}}catch(err){h.toast(runtimeError(err));}});}
async function detail(id,h){const m=await movieService.get('detail',{id,region});h.modal(h.esc(m.title),`<p class="muted">${h.esc(m.year)} · ${m.duration||'—'} dəq. · ★ ${m.rating}</p><p>${h.esc(m.description||'Təsvir yoxdur.')}</p><div class="chips">${[['favorite','Sevimli'],['watchlist','Sonra baxacağam'],['watched','Baxdım'],['disliked','Bəyənmədim']].map(([v,l])=>`<button class="chip" data-movie-status="${v}">${l}</button>`).join('')}</div><div class="row" style="margin-top:20px;flex-wrap:wrap">${m.trailer?`<a class="btn" href="${h.esc(m.trailer)}" target="_blank" rel="noopener noreferrer">Treyler</a>`:'<small>Treyler yoxdur.</small>'}${m.watchLink&&m.providers.length?`<a class="btn primary" href="${h.esc(m.watchLink)}" target="_blank" rel="noopener noreferrer">Qanuni izləmə seçimləri</a>`:'<small>Bu region üçün doğrulanmış izləmə məlumatı yoxdur.</small>'}</div><p class="format-help">${h.esc(m.providers.join(', '))} · İzləmə məlumatları: JustWatch/TMDB.</p>`);document.querySelectorAll('[data-movie-status]').forEach(b=>b.onclick=async()=>{try{await h.toggle(b.dataset.movieStatus,m.id);b.classList.toggle('active');}catch(e){h.toast(runtimeError(e));}});}
function recommend(h){h.modal('Bu axşam nə izləyim?',`<form id="real-recommend" class="form"><label>Əhvalın<select name="mood"><option value="light">Rahat və yüngül</option><option value="thoughtful">Düşündürücü</option><option value="exciting">Həyəcanlı</option></select></label><label>Janr<select name="genre"><option value="">Fərqi yoxdur</option>${genres.map(g=>`<option value="${g.id}">${h.esc(g.name)}</option>`).join('')}</select></label><label>Vaxtın<select name="duration"><option value="90">90 dəqiqəyədək</option><option value="120">2 saatadək</option><option value="180">3 saatadək</option></select></label><label>Kiminlə?<select name="company"><option value="solo">Tək</option><option value="friends">Dostlarla</option></select></label><button class="btn primary">Üç film seç</button></form><div id="recommend-results"></div>`);let next=1;const suggested=new Set();document.querySelector('#real-recommend').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const result=await movieService.get('recommend',{...Object.fromEntries(new FormData(e.target)),page:next++});const choices=result.movies.filter(m=>!h.data.watched.includes(m.id)&&!h.data.disliked.includes(m.id)&&!suggested.has(m.id)).slice(0,3);choices.forEach(m=>suggested.add(m.id));document.querySelector('#recommend-results').innerHTML=choices.length?choices.map(m=>`<button class="setting" style="width:100%;text-align:left" data-choice="${m.id}">${h.esc(m.title)} <span>★ ${m.rating} →</span></button>`).join(''):'<p>Bu seçimlərə uyğun yeni film tapılmadı.</p>';document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>detail(b.dataset.choice,h));button.textContent='Başqa seçimlər göstər';}catch(error){h.toast(runtimeError(error));}finally{button.disabled=false;}};}
